local Mercury = loadstring(game:HttpGet("https://raw.githubusercontent.com/deeeity/mercury-lib/master/src.lua"))()

-- Create GUI
local GUI = Mercury:Create{
    Name = "Main Menu",
    Size = UDim2.fromOffset(600, 400),
    Theme = Mercury.Themes.Rust,
    Link = "Main"
}
local Credits = GUI:Credit{
	Name = "OS",
	Description = "Windows NT",
	V3rm = "",
	Discord = ""
}

local Players = game:GetService("Players")
local SelectedPlayer = Players.LocalPlayer
local SettingOptions = {
    ShouldPrompt = true,
    EnableMoney = true,
    EnableRebirths = true,
    EnableChests = true
}

local function SpawnCar(vehicleName)
    if not SelectedPlayer then return end
    local character = SelectedPlayer.Character or SelectedPlayer.CharacterAdded:Wait()
    local rootPart = character:WaitForChild("HumanoidRootPart")

    local spawnPosition = rootPart.CFrame * CFrame.new(0, 5, 0)

    local args = {
        [1] = vehicleName,
        [2] = spawnPosition,
        [3] = SelectedPlayer
    }

    game:GetService("ReplicatedStorage").Vehicles.VehicleFunction:InvokeServer("SpawnVehicle", args)
end

local PlayerTab = GUI:Tab{
    Name = "Player",
    Icon = "rbxassetid://87041975967241"
}

local VehSpawner = GUI:Tab{
    Name = "Spawner",
    Icon = "rbxassetid://101646918234834"
}

local SettingsTab = GUI:Tab{
    Name = "Settings",
    Icon = "rbxassetid://14134158045"
}

SettingsTab:Toggle{
    Name = "Prompt on button click",
    StartingState = SettingOptions.ShouldPrompt,
    Description = "Toggle for the 'Are you sure?' prompt",
    Callback = function(state) SettingOptions.ShouldPrompt = state end
}

SettingsTab:Toggle{
    Name = "Enable Money Actions",
    StartingState = SettingOptions.EnableMoney,
    Description = "Toggle for enabling money-related actions",
    Callback = function(state) SettingOptions.EnableMoney = state end
}

SettingsTab:Toggle{
    Name = "Enable Rebirth Actions",
    StartingState = SettingOptions.EnableRebirths,
    Description = "Toggle for enabling rebirth-related actions",
    Callback = function(state) SettingOptions.EnableRebirths = state end
}

SettingsTab:Toggle{
    Name = "Enable Chest Actions",
    StartingState = SettingOptions.EnableChests,
    Description = "Toggle for enabling chest-related actions",
    Callback = function(state) SettingOptions.EnableChests = state end
}

local amountOfMoney = ""
local rebirthAmounts = 4
local SelectedChest = "Common"

local function executeAction(action)
    if SettingOptions.ShouldPrompt then
        GUI:Prompt{
            Followup = false,
            Title = "Are you sure?",
            Text = action.promptText,
            Buttons = {
                Yes = function()
                    action.callback()
                    task.spawn(function()
                       GUI:Notification{
                        Title = "Alert",
                        Text = "Action executed successfully!",
                        Duration = 3,
                        Callback = function() end
                    }
                    end)
                end,
                No = function() return end
            }
        }
    else
        action.callback()
        GUI:Notification{
            Title = "Alert",
            Text = "Action executed successfully!",
            Duration = 3,
            Callback = function() end
        }
    end
end

PlayerTab:TextBox{
    Name = "Amount Of Money",
    Callback = function(v)
        amountOfMoney = v
    end
}

PlayerTab:Button{
    Name = "Add Money",
    Description = nil,
    Callback = function()
        if SettingOptions.EnableMoney then
            executeAction{
                promptText = "Are you sure you want to add: " .. amountOfMoney .. " Money?",
                callback = function()
                    game:GetService("ReplicatedStorage").UpdateCash:FireServer("change", amountOfMoney)
                end
            }
        end
    end
}

PlayerTab:TextBox{
    Name = "Amount Of Rebirths",
    Callback = function(v)
        rebirthAmounts = tonumber(v) or 4
    end
}

PlayerTab:Button{
    Name = "Confirm Rebirths",
    Description = "NOTE: You will die the amount of rebirths",
    Callback = function()
        if SettingOptions.EnableRebirths then
            executeAction{
                promptText = "Are you sure you want to add: " .. rebirthAmounts .. " Rebirths?\nNOTE: You will die " .. rebirthAmounts .. " times",
                callback = function()
                    task.spawn(function()
                        for i = 1, rebirthAmounts do
                            game:GetService("ReplicatedStorage").RebirthEvent:FireServer({Type = "InitiateRebirth"})
                        end
                    end)
                end
            }
        end
    end
}

PlayerTab:Dropdown{
    Name = "Chest Giver",
    StartingText = "Common",
    Items = {
        {"Common", 1}, {"Christmas", 2}, {"Epic Mecha", 3},
        {"Legendary", 4}, {"Mecha", 5}, {"Mini", 6},
        {"Rare", 7}, {"Small Present", 8}
    },
    Description = "Give 100 of selected Chest",
    Callback = function(v)
        local chestNames = {"Common", "Christmas", "Epic Mecha", "Legendary", "Mecha", "Mini", "Rare", "Small Present"}
        SelectedChest = chestNames[v] or "Common"
    end
}

PlayerTab:Button{
    Name = "Add Chests",
    Description = nil,
    Callback = function()
        if SettingOptions.EnableChests then
            executeAction{
                promptText = "Are you sure you want to add: 100 " .. SelectedChest .. " Chests?",
                callback = function()
                    game:GetService("ReplicatedStorage").Chests.ChestFunction:InvokeServer("UpdateChests", {game.Players.LocalPlayer, SelectedChest, 100})
                end
            }
        end
    end
}

local vehicles = {}
for _, vehicle in pairs(game:GetService("ReplicatedStorage").Vehicles.Objects:GetChildren()) do
    if vehicle:IsA("Model") then
        local VehicleSettings = require(vehicle.Settings)
        table.insert(vehicles, { SpawnName = vehicle.Name, Type = VehicleSettings.Type })
    end
end

table.sort(vehicles, function(a, b) return a.SpawnName < b.SpawnName end)

for _, _vehicle in ipairs(vehicles) do
    VehSpawner:Button{
        Name = _vehicle.SpawnName,
        Description = 'Spawn: ' .. _vehicle.SpawnName .. ' (' .. _vehicle.Type .. ')',
        Callback = function()
            SpawnCar(_vehicle.SpawnName)
        end
    }
end
